import type {ComponentProps, ReactNode} from 'react';
import Metadata from '@theme-original/DocItem/Metadata';
import Head from '@docusaurus/Head';
import useBaseUrl from '@docusaurus/useBaseUrl';
import {useDoc} from '@docusaurus/plugin-content-docs/client';

// Per-page social image generated by scripts/og-images.ts (static/img/og/<docId>.png).
export default function MetadataWrapper(props: ComponentProps<typeof Metadata>): ReactNode {
  const {metadata, frontMatter} = useDoc();
  const image = useBaseUrl(`/img/og/${metadata.id}.png`, {absolute: true});
  return (
    <>
      <Metadata {...props} />
      {!frontMatter.image && (
        <Head>
          <meta property="og:image" content={image} />
          <meta name="twitter:image" content={image} />
        </Head>
      )}
    </>
  );
}
